    assert business_days_between(TUESDAY, WEDNESDAY_HOLIDAY) == 1


@pytest.mark.parametrize(
    ("start", "end"),
    [(MONDAY, MONDAY), (TUESDAY, MONDAY)],
)
def test_business_days_between_returns_zero_when_end_not_after_start(start, end):
